#!/usr/bin/env node
// Turns a product photo (default: tee.png next to this script) into 4 product
// photos with Modelfy, then prints the links to the finished photos.
//
// Usage:  MODELFY_API_KEY=mfy_... node make-photos.mjs [path/to/product.png]
//         (or put MODELFY_API_KEY in a .env file and run with --env-file=.env)

import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join, extname } from 'node:path';

const MCP_URL = 'https://dvds-scale-save-modification.trycloudflare.com/mcp';

// What the photos look like. These are my defaults; change them here if needed.
const PHOTO_SETTINGS = {
  mode: 'studio',              // plain background, product only (no model)
  background_color: 'white',
  aspect_ratio: '4:5',
  photos_per_product: 4,
  locale: 'en',
};

const CONTENT_TYPES = { '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp', '.heic': 'image/heic' };

const apiKey = process.env.MODELFY_API_KEY;
if (!apiKey) {
  console.error('MODELFY_API_KEY is not set. Put it in .env (MODELFY_API_KEY=...) and run with --env-file=.env, or export it.');
  process.exit(1);
}

const here = dirname(fileURLToPath(import.meta.url));
const imagePath = process.argv[2] ?? join(here, 'tee.png');
const contentType = CONTENT_TYPES[extname(imagePath).toLowerCase()];
if (!contentType) {
  console.error(`Unsupported image type for ${imagePath}. Use PNG, JPEG, WebP or HEIC.`);
  process.exit(1);
}

// ---- Minimal MCP client over Streamable HTTP (JSON-RPC via POST) ----------

let sessionId;
let nextId = 1;

async function rpc(method, params) {
  const r = await fetch(MCP_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json, text/event-stream',
      Authorization: `Bearer ${apiKey}`,
      ...(sessionId ? { 'mcp-session-id': sessionId } : {}),
    },
    body: JSON.stringify({ jsonrpc: '2.0', id: nextId++, method, params }),
  });
  sessionId ??= r.headers.get('mcp-session-id') ?? undefined;
  const text = await r.text();
  if (!r.ok) throw new Error(`Modelfy HTTP ${r.status}: ${text}`);
  const isSse = (r.headers.get('content-type') ?? '').includes('text/event-stream');
  const msg = isSse
    ? JSON.parse(text.split('\n').filter((l) => l.startsWith('data:')).map((l) => l.slice(5).trim()).filter(Boolean).pop())
    : JSON.parse(text);
  if (msg.error) throw new Error(`MCP error: ${msg.error.message}`);
  return msg.result;
}

async function notify(method) {
  await fetch(MCP_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json, text/event-stream',
      Authorization: `Bearer ${apiKey}`,
      ...(sessionId ? { 'mcp-session-id': sessionId } : {}),
    },
    body: JSON.stringify({ jsonrpc: '2.0', method }),
  });
}

// Calls a tool; returns structuredContent, and throws with Modelfy's error text on failure.
async function tool(name, args = {}) {
  const result = await rpc('tools/call', { name, arguments: args });
  if (result.isError) {
    const err = result.structuredContent?.error ?? {};
    const text = result.content?.map((c) => c.text).join(' ');
    throw new Error(`${name} failed${err.code ? ` [${err.code}]` : ''}: ${err.message ?? text}${err.next_step ? ` Next: ${err.next_step}` : ''}`);
  }
  return result.structuredContent ?? {};
}

const sleep = (ms) => new Promise((res) => setTimeout(res, ms));

// ---- Steps ----------------------------------------------------------------

await rpc('initialize', {
  protocolVersion: '2025-06-18',
  capabilities: {},
  clientInfo: { name: 'make-photos', version: '1.0.0' },
});
await notify('notifications/initialized');

const account = await tool('get_account');
console.log(`Account: ${account.credits} credits (${account.plan}${account.sandbox ? ', sandbox' : ''})`);

// 1. Upload the product photo.
const bytes = await readFile(imagePath);
const session = await tool('create_upload_session', { files: [{ content_type: contentType, bytes: bytes.length }] });
const upload = session.uploads?.[0];
if (!upload) throw new Error('create_upload_session returned no upload slot');
const put = await fetch(upload.put_url, { method: 'PUT', headers: upload.headers, body: bytes });
if (!put.ok) throw new Error(`Uploading ${imagePath} failed: HTTP ${put.status}`);

let ready = [];
for (let i = 0; i < 30; i++) {
  const status = await tool('get_uploaded_photos', { session_id: session.session_id });
  if (status.rejected?.length) {
    throw new Error(`Modelfy rejected the photo: ${status.rejected.map((r) => r.reason ?? JSON.stringify(r)).join('; ')}`);
  }
  if (status.ready_upload_ids?.length) { ready = status.ready_upload_ids; break; }
  if (!status.pending) break;
  await sleep(1000);
}
if (!ready.length) throw new Error('The uploaded photo never became ready.');
console.log(`Uploaded ${imagePath}`);

// 2. Plan the session: this is free and returns the exact price.
const plan = await tool('plan_photos', {
  products: [{ upload_ids: ready, name: 'Linen T-shirt' }],
  ...PHOTO_SETTINGS,
});
console.log(`Plan: ${plan.photos ?? PHOTO_SETTINGS.photos_per_product} photos for ${plan.credits} credits (balance ${plan.balance}).`);
if (plan.enough_credits === false) throw new Error('Not enough credits for this session.');

// 3. Launch it. The API key's own budget is the consent; sandbox keys spend nothing.
const launch = await tool('generate_photos', { quote_id: plan.quote_id });
const sid = launch.session_id;
if (!sid) throw new Error(`generate_photos returned no session_id: ${JSON.stringify(launch)}`);
console.log(`Launched session ${sid}`);

// 4. Wait until it finishes.
let session_;
for (let i = 0; i < 40; i++) {
  session_ = await tool('get_photo_session', { session_id: sid, wait_seconds: 45 });
  if (session_.status !== 'running') break;
}
if (session_.status === 'running') throw new Error(`Session ${sid} is still running; check it later with get_photo_session.`);

// 5. Print the links.
const photos = (session_.photos ?? []).filter((p) => p.url);
console.log(`\nStatus: ${session_.status}. ${photos.length} photo(s):`);
for (const p of photos) console.log(`  ${p.url}`);
if (session_.web_url) console.log(`All photos: ${session_.web_url}`);
if (!photos.length) {
  console.log('\nNo photo links in the response:');
  console.log(JSON.stringify(session_, null, 2));
  process.exit(1);
}

