const URL_ = "https://dvds-scale-save-modification.trycloudflare.com/mcp";
const KEY = (await import("node:fs")).readFileSync("/work/.env", "utf8").match(/MODELFY_API_KEY=(.*)/)[1].trim();

async function rpc(method, params, id = 1) {
  const res = await fetch(URL_, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${KEY}`,
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
    },
    body: JSON.stringify({ jsonrpc: "2.0", id, method, params }),
  });
  const text = await res.text();
  const line = text.split("\n").find((l) => l.startsWith("data: "));
  return JSON.parse(line ? line.slice(6) : text);
}

for (const name of process.argv.slice(2)) {
  const r = await rpc("tools/call", { name, arguments: {} });
  console.log("## " + name);
  console.log(JSON.stringify(r).slice(0, 2500));
  console.log();
}

