// Turns tee.png (a linen T-shirt) into 4 product photos with Modelfy
// and prints the links to the finished photos.
//
// Usage (Node 22+):
//   node --env-file=.env make-photos.mjs
// The script reads MODELFY_API_KEY from the environment.

import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const MCP_URL = "https://dvds-scale-save-modification.trycloudflare.com/mcp";
const PRODUCT_IMAGE = join(dirname(fileURLToPath(import.meta.url)), "tee.png");
const PHOTOS = 4;
const ASPECT_RATIO = "4:5";

const API_KEY = process.env.MODELFY_API_KEY;
if (!API_KEY) {
  console.error("MODELFY_API_KEY is not set. Run: node --env-file=.env make-photos.mjs");
  process.exit(1);
}

let rpcId = 0;
let mcpSessionId = null;

// One JSON-RPC request over Streamable HTTP. The server answers with SSE.
async function rpc(method, params) {
  const headers = {
    Authorization: `Bearer ${API_KEY}`,
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
  };
  if (mcpSessionId) headers["Mcp-Session-Id"] = mcpSessionId;

  const res = await fetch(MCP_URL, {
    method: "POST",
    headers,
    body: JSON.stringify({ jsonrpc: "2.0", id: ++rpcId, method, params }),
  });
  const sid = res.headers.get("mcp-session-id");
  if (sid) mcpSessionId = sid;
  const text = await res.text();
  if (!res.ok) throw new Error(`HTTP ${res.status} on ${method}: ${text.slice(0, 500)}`);
  const dataLine = text.split("\n").find((l) => l.startsWith("data: "));
  const msg = JSON.parse(dataLine ? dataLine.slice(6) : text);
  if (msg.error) throw new Error(`${method} failed: ${JSON.stringify(msg.error)}`);
  return msg.result;
}

// Call a Modelfy tool and return its structured result. Throws on tool errors.
async function tool(name, args = {}) {
  const result = await rpc("tools/call", { name, arguments: args });
  if (result.structuredContent === undefined && result.isError) {
    throw new Error(`${name} error: ${result.content?.map((c) => c.text).join(" ")}`);
  }
  if (result.isError) {
    throw new Error(`${name} error: ${JSON.stringify(result.structuredContent ?? result.content)}`);
  }
  return result.structuredContent;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function uploadProduct() {
  const bytes = await readFile(PRODUCT_IMAGE);
  const session = await tool("create_upload_session", {
    files: [{ content_type: "image/png", bytes: bytes.length }],
  });
  const file = session.files?.[0];
  if (!file?.put_url) throw new Error(`no upload URL returned: ${JSON.stringify(session)}`);

  const put = await fetch(file.put_url, {
    method: "PUT",
    headers: file.headers ?? { "Content-Type": "image/png" },
    body: bytes,
  });
  if (!put.ok) throw new Error(`upload failed: HTTP ${put.status} ${await put.text()}`);

  // Wait until Modelfy has checked the file.
  for (let i = 0; i < 30; i++) {
    const got = await tool("get_uploaded_photos", { session_id: session.session_id });
    const ready = got.ready ?? got.photos?.filter((p) => p.upload_id) ?? [];
    if (ready.length > 0) return ready[0].upload_id;
    if (got.rejected?.length) throw new Error(`product photo rejected: ${JSON.stringify(got.rejected)}`);
    if (!got.pending) break;
    await sleep(2000);
  }
  throw new Error("product photo was not ready in time");
}

async function main() {
  const account = await tool("get_account");
  console.log(`Account: ${account.plan}, ${account.credits} credits${account.sandbox ? " (sandbox: nothing is spent, photos are samples)" : ""}`);

  console.log("Uploading tee.png...");
  const uploadId = await uploadProduct();

  const { models } = await tool("list_models");
  const model = models.find((m) => m.ready);
  const { backgrounds } = await tool("list_backgrounds");
  const background = backgrounds.find((b) => b.ready);
  if (!model || !background) throw new Error("no ready model or background available");
  console.log(`Model: ${model.name}. Place: ${background.name}.`);

  const plan = await tool("plan_photos", {
    products: [{ upload_ids: [uploadId], name: "Linen T-shirt" }],
    mode: "place",
    model_ids: [model.id],
    background_id: background.id,
    aspect_ratio: ASPECT_RATIO,
    photos_per_product: PHOTOS,
    direction: "relaxed, natural light",
    locale: "en",
  });
  console.log(`Plan: ${PHOTOS} photos for ${plan.credits} credits${plan.enough_credits === false ? " (NOT ENOUGH CREDITS)" : ""}.`);
  if (plan.enough_credits === false) throw new Error("not enough credits for this plan");

  const launched = await tool("generate_photos", {
    quote_id: plan.quote_id,
    user_confirmed: true,
  });
  const sessionId = launched.session_id;
  console.log(`Session ${sessionId} started. Waiting for photos...`);

  let session;
  for (;;) {
    session = await tool("get_photo_session", { session_id: sessionId, wait_seconds: 45 });
    if (session.status !== "running") break;
  }

  console.log(`Status: ${session.status}`);
  const photos = session.photos ?? [];
  for (const p of photos) {
    if (p.url) console.log(p.url);
    else console.log(`(failed: ${p.error ?? p.status ?? "unknown"})`);
  }
  if (session.web_url) console.log(`All photos: ${session.web_url}`);

  const done = photos.filter((p) => p.url).length;
  if (done === 0) process.exit(1);
  if (done < PHOTOS) console.log(`Only ${done} of ${PHOTOS} photos were made; the rest were refunded.`);
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

