// Turns tee.png (a linen T-shirt) into 4 studio product photos with Modelfy
// and prints the links to the finished photos.
//
// Usage:  node --env-file=.env make-photos.mjs [path/to/product.png]
// Needs:  MODELFY_API_KEY in the environment (mfy_test_… or mfy_live_…)
// Needs:  npm install @modelcontextprotocol/sdk

import { readFile } from "node:fs/promises";
import { basename, extname } from "node:path";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";

const MCP_URL = "https://dvds-scale-save-modification.trycloudflare.com/mcp";
const HERE = dirname(fileURLToPath(import.meta.url));

const PRODUCT_FILE = process.argv[2] ?? join(HERE, "tee.png");
const PRODUCT_NAME = "Linen T-shirt";
const PHOTO_COUNT = 4;
const ASPECT_RATIO = "4:5";
const BACKGROUND = "light grey";

const CONTENT_TYPES = {
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".webp": "image/webp",
};

const apiKey = process.env.MODELFY_API_KEY;
if (!apiKey) {
  console.error("MODELFY_API_KEY is not set. Put it in .env and run with --env-file=.env");
  process.exit(1);
}

const client = new Client({ name: "make-photos", version: "1.0.0" });
await client.connect(
  new StreamableHTTPClientTransport(new URL(MCP_URL), {
    requestInit: { headers: { Authorization: `Bearer ${apiKey}` } },
  }),
);

// Calls an MCP tool and returns its structured JSON result. Throws on tool errors.
async function call(name, args = {}) {
  const result = await client.callTool({ name, arguments: args });
  const payload = result.structuredContent ?? JSON.parse(result.content.find((c) => c.type === "text" && c.text.startsWith("{"))?.text ?? "{}");
  if (result.isError) {
    const err = payload.error ?? {};
    throw new Error(`${name} failed: ${err.code ?? "ERROR"}: ${err.message ?? JSON.stringify(payload)}${err.next_step ? ` (next: ${err.next_step})` : ""}`);
  }
  return payload;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

try {
  // 1. Account: who is paying, and how many credits are there.
  const account = await call("get_account");
  console.log(`Account: ${account.plan} (${account.keyKind}), ${account.credits} credits`);

  // 2. Options: make sure the format and photo count are allowed.
  const options = await call("get_photo_options");
  if (!options.aspectRatios.includes(ASPECT_RATIO)) throw new Error(`Aspect ratio ${ASPECT_RATIO} not offered: ${options.aspectRatios}`);
  const { min, max } = options.photosPerProduct;
  if (PHOTO_COUNT < min || PHOTO_COUNT > max) throw new Error(`Photos per product must be ${min}-${max}`);

  // 3. Upload the product photo from this machine (bytes go straight to the presigned PUT URL).
  const bytes = await readFile(PRODUCT_FILE);
  const contentType = CONTENT_TYPES[extname(PRODUCT_FILE).toLowerCase()];
  if (!contentType) throw new Error(`Unsupported file type: ${PRODUCT_FILE}`);

  const session = await call("create_upload_session", { files: [{ content_type: contentType, bytes: bytes.length }] });
  const target = session.uploads[0];
  const put = await fetch(target.put_url, {
    method: "PUT",
    headers: target.headers,
    body: bytes,
  });
  if (!put.ok) throw new Error(`Upload of ${basename(PRODUCT_FILE)} failed: HTTP ${put.status}`);

  // Wait until Modelfy has accepted the file.
  let uploaded;
  for (let i = 0; i < 20; i++) {
    uploaded = await call("get_uploaded_photos", { session_id: session.session_id });
    if (uploaded.rejected?.length) {
      throw new Error(`Photo rejected: ${JSON.stringify(uploaded.rejected)}`);
    }
    if (!uploaded.pending) break;
    await sleep(2000);
  }
  const uploadIds = (uploaded.ready ?? []).map((p) => p.upload_id);
  if (uploadIds.length === 0) throw new Error(`No upload ready: ${JSON.stringify(uploaded)}`);
  console.log(`Uploaded ${basename(PRODUCT_FILE)} as ${uploadIds[0]}`);

  // 4. Plan: the exact price comes back with a quote_id. Nothing is spent yet.
  const plan = await call("plan_photos", {
    products: [{ upload_ids: uploadIds, name: PRODUCT_NAME }],
    mode: "studio",
    background_color: BACKGROUND,
    aspect_ratio: ASPECT_RATIO,
    photos_per_product: PHOTO_COUNT,
    direction: "clean product shot, even natural light",
    locale: "en",
  });
  console.log(`Plan: ${PHOTO_COUNT} photos for ${plan.credits} credits (balance ${plan.balance})`);
  if (!plan.enough_credits) throw new Error("Not enough credits for this plan");

  // 5. Launch. The key's own budget (or sandbox) is the consent; the user asked for this run.
  const launch = await call("generate_photos", { quote_id: plan.quote_id, user_confirmed: true });
  const sessionId = launch.session_id;
  console.log(`Session ${sessionId} started`);

  // 6. Wait for the photos.
  let photoSession;
  for (let i = 0; i < 40; i++) {
    photoSession = await call("get_photo_session", { session_id: sessionId, wait_seconds: 45 });
    if (photoSession.status !== "running") break;
    console.log(`  still running...`);
  }
  console.log(`Status: ${photoSession.status}`);

  // 7. Print the links.
  const photos = photoSession.photos ?? [];
  for (const p of photos) {
    console.log(p.url ?? `(no link) ${JSON.stringify(p)}`);
  }
  if (photoSession.web_url) console.log(`All photos: ${photoSession.web_url}`);
  if (!photos.some((p) => p.url)) process.exitCode = 1;
} finally {
  await client.close();
}

