input.content:
// Turns tee.png (a linen T-shirt) into 4 product photos with Modelfy and prints the links.
// Run:  node --env-file=.env make-photos.mjs
// Needs MODELFY_API_KEY in the environment.

import { readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const MCP_URL = "https://dvds-scale-save-modification.trycloudflare.com/mcp";
const PHOTO_COUNT = 4;
const ASPECT_RATIO = "4:5";
const IMAGE_PATH = join(dirname(fileURLToPath(import.meta.url)), "tee.png");

const API_KEY = process.env.MODELFY_API_KEY;
if (!API_KEY) {
  console.error("MODELFY_API_KEY is not set. Put it in .env and run: node --env-file=.env make-photos.mjs");
  process.exit(1);
}

// ---------- minimal MCP client (Streamable HTTP) ----------

let sessionId = null;
let nextId = 1;

async function rpc(method, params, { notification = false } = {}) {
  const body = { jsonrpc: "2.0", method, params };
  if (!notification) body.id = nextId++;
  const headers = {
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    Authorization: `Bearer ${API_KEY}`,
    "MCP-Protocol-Version": "2025-06-18",
  };
  if (sessionId) headers["Mcp-Session-Id"] = sessionId;

  const res = await fetch(MCP_URL, { method: "POST", headers, body: JSON.stringify(body) });
  const sid = res.headers.get("mcp-session-id");
  if (sid) sessionId = sid;
  if (notification) return null;

  const text = await res.text();
  if (!res.ok) throw new Error(`HTTP ${res.status} from ${method}: ${text.slice(0, 300)}`);

  // Response is either plain JSON or an SSE stream with one "data:" message per event.
  let message;
  if ((res.headers.get("content-type") || "").includes("text/event-stream")) {
    const dataLines = text.split("\n").filter((l) => l.startsWith("data:")).map((l) => l.slice(5).trim());
    message = dataLines.map((d) => JSON.parse(d)).find((m) => m.id === body.id);
  } else {
    message = JSON.parse(text);
  }
  if (!message) throw new Error(`No response for ${method}`);
  if (message.error) throw new Error(`${method} failed: ${JSON.stringify(message.error)}`);
  return message.result;
}

// Calls a tool and returns its structured result. Throws on tool errors, with the Modelfy error code attached.
async function callTool(name, args, { retries = 3 } = {}) {
  for (let attempt = 1; ; attempt++) {
    const result = await rpc("tools/call", { name, arguments: args });
    const payload = result.structuredContent ?? JSON.parse(result.content?.find((c) => c.type === "text")?.text ?? "{}");
    if (!result.isError) return payload;

    const err = payload.error ?? {};
    const retryable = err.code === "RATE_LIMITED" || err.code === "MODELFY_ERROR";
    if (retryable && attempt <= retries) {
      console.log(`  ${name}: ${err.code}, retrying in ${attempt * 5}s...`);
      await new Promise((r) => setTimeout(r, attempt * 5000));
      continue;
    }
    const e = new Error(`${name} failed: ${err.code ?? "UNKNOWN"}: ${err.message ?? JSON.stringify(payload)}`);
    e.modelfyError = err;
    throw e;
  }
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---------- the job ----------

async function main() {
  await rpc("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "make-photos", version: "1.0.0" },
  });
  await rpc("notifications/initialized", {}, { notification: true });

  const account = await callTool("get_account", {});
  console.log(`Key: ${account.keyKind}${account.sandbox ? " (sandbox: nothing is spent, photos are samples marked SANDBOX)" : ""}`);
  console.log(`Credits: ${account.credits}`);

  const options = await callTool("get_photo_options", {});
  if (!options.aspectRatios.includes(ASPECT_RATIO)) {
    throw new Error(`Aspect ratio ${ASPECT_RATIO} not offered. Available: ${options.aspectRatios.join(", ")}`);
  }
  if (PHOTO_COUNT < options.photosPerProduct.min || PHOTO_COUNT > options.photosPerProduct.max) {
    throw new Error(`Photos per product must be ${options.photosPerProduct.min}-${options.photosPerProduct.max}`);
  }

  // 1. Upload the product photo from local bytes (the bytes never go through the model).
  const bytes = await readFile(IMAGE_PATH);
  const upload = await callTool("create_upload_session", {
    files: [{ content_type: "image/png", bytes: bytes.length }],
  });
  const target = upload.uploads[0];
  const put = await fetch(target.put_url, { method: "PUT", headers: target.headers, body: bytes });
  if (!put.ok) throw new Error(`Upload failed: HTTP ${put.status} ${await put.text()}`);
  console.log(`Uploaded tee.png (${bytes.length} bytes)`);

  let ready = [];
  for (let i = 0; i < 30; i++) {
    const status = await callTool("get_uploaded_photos", { session_id: upload.session_id });
    if (status.rejected.length) {
      throw new Error(`Product photo rejected: ${status.rejected.map((r) => r.reason).join("; ")}`);
    }
    if (status.pending === 0 && status.ready_upload_ids.length) {
      ready = status.ready_upload_ids;
      break;
    }
    await sleep(2000);
  }
  if (!ready.length) throw new Error("Product photo never became ready");

  // 2. Plan: product alone on a plain white studio background, 4 photos.
  const quote = await callTool("plan_photos", {
    products: [{ upload_ids: [ready[0]], name: "Linen T-shirt" }],
    mode: "studio",
    background_color: "white",
    aspect_ratio: ASPECT_RATIO,
    photos_per_product: PHOTO_COUNT,
    locale: "en",
  });
  console.log(`Planned ${quote.photos} photos for ${quote.credits} credits (balance ${quote.balance})`);
  if (!quote.enough_credits) throw new Error("Not enough credits for this session");

  // 3. Launch. A script run with a live key is consented to by that key's budget;
  //    the sandbox spends nothing. The quote_id makes a retry safe (never charges twice).
  const launched = await callTool("generate_photos", { quote_id: quote.quote_id, user_confirmed: true });
  console.log(`Session started: ${launched.name} (${launched.session_id})`);

  // 4. Wait until done.
  let session = launched;
  while (session.status === "running") {
    session = await callTool("get_photo_session", { session_id: launched.session_id, wait_seconds: 45 });
    console.log(`  status: ${session.status} (${session.done}/${session.total} done)`);
  }

  console.log(`\nSession ${session.status}. Credits charged ${session.credits.charged}, refunded ${session.credits.refunded}.`);
  if (session.photos.length === 0) throw new Error(`No photos were made (status ${session.status})`);
  console.log("Photos:");
  for (const p of session.photos) console.log(`  ${p.url}`);
  console.log(`Session page: ${session.web_url}`);
}

main().catch((err) => {
  console.error(`Error: ${err.message}`);
  process.exit(1);
});

