#!/usr/bin/env node
// Turns tee.png (a linen T-shirt) into 4 product photos with Modelfy and prints the links.
//
// Usage:
//   node --env-file=.env make-photos.mjs            (reads MODELFY_API_KEY from .env)
//   MODELFY_API_KEY=mfy_... node make-photos.mjs    (or from the environment)

import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const MCP_URL = "https://dvds-scale-save-modification.trycloudflare.com/mcp";
const PHOTO_COUNT = 4;
const ASPECT_RATIO = "4:5"; // one of get_photo_options aspectRatios
const MODEL_IDS = ["sbx_model_ana"]; // from list_models; [] gives product-only photos
const BACKGROUND_ID = "sbx_set_terrace"; // from list_backgrounds
const PRODUCT_NAME = "Linen T-shirt";
const PRODUCT_DESCRIPTION = "Linen T-shirt, product photo from tee.png";
const LOCALE = "en";
const SESSION_WAIT_SECONDS = 45;
const MAX_WAIT_ROUNDS = 20; // about 15 minutes at 45 s per round

const here = dirname(fileURLToPath(import.meta.url));
const IMAGE_PATH = join(here, "tee.png");

const apiKey = process.env.MODELFY_API_KEY;
if (!apiKey) {
  console.error("MODELFY_API_KEY is not set. Put it in .env or the environment.");
  process.exit(1);
}

// ---- Minimal MCP client over Streamable HTTP ------------------------------

let sessionId;
let rpcId = 0;

async function rpc(method, params) {
  const headers = {
    Authorization: `Bearer ${apiKey}`,
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    "MCP-Protocol-Version": "2025-06-18",
  };
  if (sessionId) headers["Mcp-Session-Id"] = sessionId;

  const res = await fetch(MCP_URL, {
    method: "POST",
    headers,
    body: JSON.stringify({ jsonrpc: "2.0", id: ++rpcId, method, params }),
  });
  sessionId ??= res.headers.get("mcp-session-id") ?? undefined;
  if (!res.ok) throw new Error(`${method}: HTTP ${res.status} ${await res.text()}`);

  const text = await res.text();
  const dataLine = text.split("\n").find((l) => l.startsWith("data:"));
  const message = JSON.parse(dataLine ? dataLine.slice(5) : text);
  if (message.error) throw new Error(`${method}: ${JSON.stringify(message.error)}`);
  return message.result;
}

async function initialize() {
  await rpc("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "make-photos", version: "1.0.0" },
  });
  // Notification (no id, no response expected).
  await fetch(MCP_URL, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
      "MCP-Protocol-Version": "2025-06-18",
      ...(sessionId ? { "Mcp-Session-Id": sessionId } : {}),
    },
    body: JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" }),
  });
}

// Calls a Modelfy tool and returns its JSON payload. Throws on tool errors,
// printing the error code and the next step the docs give.
async function tool(name, args = {}) {
  const result = await rpc("tools/call", { name, arguments: args });
  const payload = result.structuredContent ?? parseTextJson(result.content);
  if (result.isError) {
    const err = payload?.error ?? {};
    const msg = [
      `${name} failed${err.code ? `: ${err.code}` : ""}`,
      err.message ?? result.content?.map((c) => c.text).join(" "),
      err.next_step ? `Next step: ${err.next_step}` : null,
    ].filter(Boolean).join("\n");
    throw new Error(msg);
  }
  return payload;
}

// Fallback when the server does not send structuredContent: the JSON is the
// last line of the text content.
function parseTextJson(content = []) {
  for (const c of content) {
    if (c.type !== "text") continue;
    const lines = c.text.trim().split("\n");
    for (let i = lines.length - 1; i >= 0; i--) {
      try {
        return JSON.parse(lines.slice(i).join("\n"));
      } catch {
        /* keep looking */
      }
    }
  }
  return undefined;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- The workflow ---------------------------------------------------------

async function uploadProductImage() {
  const bytes = await readFile(IMAGE_PATH);
  const contentType = "image/png";

  const session = await tool("create_upload_session", {
    files: [{ content_type: contentType, bytes: bytes.length }],
  });
  const file = session.files?.[0] ?? session.uploads?.[0];
  if (!file?.put_url) {
    throw new Error(`Unexpected create_upload_session response: ${JSON.stringify(session)}`);
  }

  // Send the bytes from code, not through the model. Use exactly the headers returned.
  const put = await fetch(file.put_url, {
    method: "PUT",
    headers: file.headers ?? { "Content-Type": contentType },
    body: bytes,
  });
  if (!put.ok) throw new Error(`Upload failed: HTTP ${put.status} ${await put.text()}`);

  // Wait until Modelfy has accepted the file.
  for (let i = 0; i < 30; i++) {
    const got = await tool("get_uploaded_photos", { session_id: session.session_id });
    const rejected = got.rejected ?? [];
    if (rejected.length) {
      throw new Error(`Modelfy rejected tee.png: ${JSON.stringify(rejected)}`);
    }
    const ready = got.ready ?? got.photos ?? [];
    if (ready.length && !(got.pending > 0)) return ready[0].upload_id;
    await sleep(2000);
  }
  throw new Error("Timed out waiting for Modelfy to accept tee.png");
}

async function main() {
  await initialize();

  const account = await tool("get_account");
  console.log(`Account: ${account.credits ?? "?"} credits (${account.plan ?? "?"}, key: ${account.keyKind ?? "?"})`);

  console.log("Uploading tee.png...");
  const uploadId = await uploadProductImage();
  console.log(`  upload_id ${uploadId}`);

  console.log("Planning photos...");
  const quote = await tool("plan_photos", {
    products: [{ upload_ids: [uploadId], name: PRODUCT_NAME, description: PRODUCT_DESCRIPTION }],
    mode: "place",
    model_ids: MODEL_IDS,
    background_id: BACKGROUND_ID,
    aspect_ratio: ASPECT_RATIO,
    photos_per_product: PHOTO_COUNT,
    direction: "relaxed, natural light",
    locale: LOCALE,
  });
  console.log(`  quote ${quote.quote_id}: ${quote.credits} credits, ${quote.photos} photos`);
  if (quote.enough_credits === false) {
    throw new Error(`Not enough credits: the plan costs ${quote.credits}, balance ${quote.balance}.`);
  }

  console.log("Launching...");
  const launch = await tool("generate_photos", { quote_id: quote.quote_id });
  const sessionIdModelfy = launch.session_id;
  console.log(`  session ${sessionIdModelfy}`);

  let session;
  for (let round = 1; round <= MAX_WAIT_ROUNDS; round++) {
    session = await tool("get_photo_session", {
      session_id: sessionIdModelfy,
      wait_seconds: SESSION_WAIT_SECONDS,
    });
    if (session.status !== "running") break;
    console.log(`  still running (round ${round})...`);
  }
  if (session.status === "running") {
    throw new Error(`Session ${sessionIdModelfy} is still running. Check it later with get_photo_session.`);
  }

  console.log(`\nSession ${session.status}${session.web_url ? `: ${session.web_url}` : ""}`);
  const photos = session.photos ?? [];
  for (const p of photos) {
    const status = p.status ? ` [${p.status}]` : "";
    console.log(`${p.url ?? "(no link)"}${status}`);
  }
  if (session.status !== "completed" && session.status !== "partial") {
    process.exitCode = 1;
  }
}

main().catch((err) => {
  console.error(`\nError: ${err.message}`);
  process.exit(1);
});

