input.command:
KEY=$(grep '^MODELFY_API_KEY=' .env | cut -d= -f2-) && URL=https://dvds-scale-save-modification.trycloudflare.com/mcp && H=(-H "Authorization: Bearer $KEY" -H "Content-Type: application/json" -H "Accept: application/json, text/event-stream" -H "MCP-Protocol-Version: 2025-06-18") && 
INIT=$(curl -sS -m 30 -D /tmp/mf_hdr -X POST "$URL" "${H[@]}" -d '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-06-18","capabilities":{},"clientInfo":{"name":"store-bot","version":"0.1"}}}'); echo "$INIT" | head -c 600; echo; SID=$(grep -i '^mcp-session-id:' /tmp/mf_hdr | tr -d '\r' | awk '{print $2}');
curl -sS -m 30 -X POST "$URL" "${H[@]}" ${SID:+-H "Mcp-Session-Id: $SID"} -d '{"jsonrpc":"2.0","method":"notifications/initialized"}' >/dev/null;
curl -sS -m 30 -X POST "$URL" "${H[@]}" ${SID:+-H "Mcp-Session-Id: $SID"} -d '{"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"get_account","arguments":{}}}' | head -c 1500; echo

